    /** رده‌ی متناسب با رنک فعلی کاراکتر (بدون تغییر در مکانیک؛ فقط نمایش). */
    fun rockerboyBandFor(rank: Int): FanImpactBand =
        rockerboyBands.firstOrNull { rank in it.range } ?: rockerboyBands.first()
}
